-- generated by scripts/gen_dbt.py from config/suppressions.yaml; do not edit
select
    company_id,
    sector,
    (case when company_type not in ('ltd', 'llp') then 1 else 0 end)
    + (case when status <> 'active' then 2 else 0 end)
    + (case when age_months < 6 then 4 else 0 end)
    + (case when coalesce(existing_customer, false) then 8 else 0 end)
    + (case when coalesce(open_application, false) then 16 else 0 end)
    + (case when days_since_decline < 90 then 32 else 0 end)
    + (case when coalesce(objected, false) then 64 else 0 end)
    + (case when coalesce(gone_away, false) then 128 else 0 end)
    + (case when coalesce(mps_director, false) then 256 else 0 end)
    + (case when days_since_last_letter < 56 then 512 else 0 end)
    + (case when days_since_holdout < 60 then 1024 else 0 end)
    + (case when letters_last_365 >= 6 then 2048 else 0 end)
    as suppression_mask
from {{ ref('stg_companies') }}
